//! Minimal terminal color/style handling producing the same escape
//! sequences as the reference implementation.

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DynColor {
    /// Foreground SGR code (30-37, 39, 90-97).
    Ansi(u8),
    Rgb(u8, u8, u8),
}

impl DynColor {
    pub const DEFAULT: DynColor = DynColor::Ansi(39);
    pub const BLACK: DynColor = DynColor::Ansi(30);
    pub const RED: DynColor = DynColor::Ansi(31);
    pub const GREEN: DynColor = DynColor::Ansi(32);
    pub const YELLOW: DynColor = DynColor::Ansi(33);
    pub const BLUE: DynColor = DynColor::Ansi(34);
    pub const MAGENTA: DynColor = DynColor::Ansi(35);
    pub const CYAN: DynColor = DynColor::Ansi(36);
    pub const WHITE: DynColor = DynColor::Ansi(37);

    pub fn fg_code(&self) -> String {
        match *self {
            DynColor::Ansi(c) => c.to_string(),
            DynColor::Rgb(r, g, b) => format!("38;2;{};{};{}", r, g, b),
        }
    }

    pub fn bg_code(&self) -> String {
        match *self {
            DynColor::Ansi(c) => (c + 10).to_string(),
            DynColor::Rgb(r, g, b) => format!("48;2;{};{};{}", r, g, b),
        }
    }

    pub fn from_num(n: u8) -> DynColor {
        match n {
            0..=7 => DynColor::Ansi(30 + n),
            8..=15 => DynColor::Ansi(90 + n - 8),
            _ => DynColor::DEFAULT,
        }
    }
}

/// `text` colored with a foreground color only: ESC[<fg>m text ESC[39m
pub fn fg(text: &str, c: DynColor) -> String {
    format!("\x1b[{}m{}\x1b[39m", c.fg_code(), text)
}

/// `text` with a background color only: ESC[<bg>m text ESC[49m
pub fn bg(text: &str, c: DynColor) -> String {
    format!("\x1b[{}m{}\x1b[49m", c.bg_code(), text)
}

/// `text` styled with color (+ optional bold): ESC[<fg>(;1)m text ESC[0m
pub fn styled(text: &str, c: DynColor, bold: bool) -> String {
    if bold {
        format!("\x1b[{};1m{}\x1b[0m", c.fg_code(), text)
    } else {
        format!("\x1b[{}m{}\x1b[0m", c.fg_code(), text)
    }
}
EOF
