//! Git repository metrics.

use git2::{Oid, Repository};
use regex::Regex;
use std::collections::{BinaryHeap, HashMap, HashSet};

#[derive(Clone, Copy, Debug)]
pub struct GitTime {
    pub seconds: i64,
    #[allow(dead_code)]
    pub offset_minutes: i32,
}

#[derive(Clone, Debug)]
pub struct Author {
    pub name: String,
    pub email: String,
    pub nbr_of_commits: usize,
    pub contribution: usize,
}

pub struct CommitMetrics {
    pub authors: Vec<Author>,
    pub total_number_of_authors: usize,
    pub total_number_of_commits: usize,
    pub is_shallow: bool,
    pub file_churns: Vec<(String, usize)>,
    pub churn_pool_size: usize,
    pub time_of_most_recent_commit: Option<GitTime>,
    pub time_of_first_commit: Option<GitTime>,
}

pub struct TraverseOptions<'a> {
    pub no_bots: Option<&'a Regex>,
    pub no_merges: bool,
    pub churn_pool_size: Option<usize>,
    pub number_of_authors: usize,
    pub number_of_file_churns: usize,
}

#[derive(PartialEq, Eq)]
struct QueueItem {
    time: i64,
    seq: std::cmp::Reverse<u64>,
    oid: Oid,
}
impl Ord for QueueItem {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        self.time.cmp(&other.time).then(self.seq.cmp(&other.seq))
    }
}
impl PartialOrd for QueueItem {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        Some(self.cmp(other))
    }
}

/// Walks ancestors of `start`, newest commit time first.
fn walk_commits(repo: &Repository, start: Oid) -> Vec<git2::Commit<'_>> {
    let mut out = Vec::new();
    let mut seen: HashSet<Oid> = HashSet::new();
    let mut heap = BinaryHeap::new();
    let mut seq = 0u64;
    let first = match repo.find_commit(start) {
        Ok(c) => c,
        Err(_) => return out,
    };
    seen.insert(start);
    heap.push(QueueItem { time: first.time().seconds(), seq: std::cmp::Reverse(seq), oid: start });
    let mut cache: HashMap<Oid, git2::Commit> = HashMap::new();
    cache.insert(start, first);
    while let Some(item) = heap.pop() {
        let commit = match cache.remove(&item.oid) {
            Some(c) => c,
            None => continue,
        };
        for pid in commit.parent_ids() {
            if seen.insert(pid) {
                if let Ok(p) = repo.find_commit(pid) {
                    seq += 1;
                    heap.push(QueueItem { time: p.time().seconds(), seq: std::cmp::Reverse(seq), oid: pid });
                    cache.insert(pid, p);
                }
            }
        }
        out.push(commit);
    }
    out
}

fn parent_count_existing(repo: &Repository, c: &git2::Commit) -> usize {
    c.parent_ids().filter(|p| repo.find_commit(*p).is_ok()).count()
}

pub fn default_bot_regex() -> Regex {
    Regex::new(r"(?:-|\s)[Bb]ot$|\[[Bb]ot\]").unwrap()
}

fn default_churn_pool(total: usize) -> usize {
    // The reference implementation computes this concurrently with the
    // commit traversal; for small histories it is effectively 1.
    let est = if total > 30 { 1 + total / 15 } else { 1 };
    est.max(1)
}

pub fn traverse(repo: &Repository, head: Oid, opts: &TraverseOptions) -> CommitMetrics {
    let mailmap = repo.mailmap().ok();
    let commits = walk_commits(repo, head);
    let mut by_sig: HashMap<(String, String), usize> = HashMap::new();
    let mut counted: Vec<&git2::Commit> = Vec::new();
    let mut most_recent: Option<GitTime> = None;
    let mut first: Option<GitTime> = None;
    for c in &commits {
        if opts.no_merges && parent_count_existing(repo, c) > 1 {
            continue;
        }
        let t = c.committer().when();
        let gt = GitTime { seconds: t.seconds(), offset_minutes: t.offset_minutes() };
        if most_recent.is_none() {
            most_recent = Some(gt);
        }
        first = Some(gt);
        let author = c.author();
        let (name, email) = match &mailmap {
            Some(mm) => match mm.resolve_signature(&author) {
                Ok(s) => (
                    String::from_utf8_lossy(s.name_bytes()).into_owned(),
                    String::from_utf8_lossy(s.email_bytes()).into_owned(),
                ),
                Err(_) => (
                    String::from_utf8_lossy(author.name_bytes()).into_owned(),
                    String::from_utf8_lossy(author.email_bytes()).into_owned(),
                ),
            },
            None => (
                String::from_utf8_lossy(author.name_bytes()).into_owned(),
                String::from_utf8_lossy(author.email_bytes()).into_owned(),
            ),
        };
        if let Some(re) = opts.no_bots {
            if re.is_match(&name) {
                continue;
            }
        }
        *by_sig.entry((name, email)).or_insert(0) += 1;
        counted.push(c);
    }
    let total = counted.len();
    let mut authors: Vec<((String, String), usize)> = by_sig.into_iter().collect();
    authors.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0 .0.cmp(&b.0 .0)).then_with(|| a.0 .1.cmp(&b.0 .1)));
    let total_number_of_authors = authors.len();
    let authors: Vec<Author> = authors
        .into_iter()
        .take(opts.number_of_authors)
        .map(|((name, email), n)| Author {
            name,
            email,
            nbr_of_commits: n,
            contribution: if total == 0 { 0 } else { ((n as f64 / total as f64) * 100.0).round() as usize },
        })
        .collect();

    // churn
    let pool = match opts.churn_pool_size {
        Some(p) => p.min(total),
        None => default_churn_pool(total).min(total),
    };
    let mut churn: HashMap<String, usize> = HashMap::new();
    let mut computed = 0usize;
    for c in counted.iter().take(pool) {
        compute_diff(repo, c, &mut churn);
        computed += 1;
    }
    let mut churns: Vec<(String, usize)> = churn.into_iter().collect();
    churns.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    churns.truncate(opts.number_of_file_churns);

