        authors,
        total_number_of_authors,
        total_number_of_commits: total,
        is_shallow: repo.is_shallow(),
        file_churns: churns,
        churn_pool_size: computed,
        time_of_most_recent_commit: most_recent,
        time_of_first_commit: first,
    }
}

fn compute_diff(repo: &Repository, c: &git2::Commit, churn: &mut HashMap<String, usize>) {
    let parents: Vec<git2::Commit> = c.parent_ids().filter_map(|p| repo.find_commit(p).ok()).collect();
    let parent_tree = match parents.len() {
        0 => None,
        1 => match parents[0].tree() {
            Ok(t) => Some(t),
            Err(_) => return,
        },
        _ => return,
    };
    let tree = match c.tree() {
        Ok(t) => t,
        Err(_) => return,
    };
    let mut dopts = git2::DiffOptions::new();
    let mut diff = match repo.diff_tree_to_tree(parent_tree.as_ref(), Some(&tree), Some(&mut dopts)) {
        Ok(d) => d,
        Err(_) => return,
    };
    let mut fopts = git2::DiffFindOptions::new();
    fopts.renames(true);
    let _ = diff.find_similar(Some(&mut fopts));
    for delta in diff.deltas() {
        match delta.status() {
            git2::Delta::Deleted => continue,
            _ => {
                if let Some(p) = delta.new_file().path() {
                    let s = p.to_string_lossy().into_owned();
                    *churn.entry(s).or_insert(0) += 1;
                }
            }
        }
    }
}

pub struct Pending {
    pub added: usize,
    pub deleted: usize,
    pub modified: usize,
}

pub fn pending(repo: &Repository) -> Pending {
    let mut opts = git2::StatusOptions::new();
    opts.include_untracked(true)
        .recurse_untracked_dirs(true)
        .include_ignored(false)
        .exclude_submodules(true)
        .renames_index_to_workdir(false)
        .renames_head_to_index(false);
    let mut p = Pending { added: 0, deleted: 0, modified: 0 };
    if let Ok(st) = repo.statuses(Some(&mut opts)) {
        for e in st.iter() {
            let s = e.status();
            if s.contains(git2::Status::WT_NEW) {
                p.added += 1;
            } else if s.contains(git2::Status::WT_DELETED) {
                p.deleted += 1;
            } else if s.intersects(git2::Status::WT_MODIFIED | git2::Status::WT_TYPECHANGE | git2::Status::WT_RENAMED) {
                p.modified += 1;
            }
        }
    }
    p
}

pub fn version(repo: &Repository) -> String {
    let mut best: Option<(i64, String)> = None;
    let mut names: Vec<String> = Vec::new();
    if let Ok(refs) = repo.references_glob("refs/tags/*") {
        for r in refs.flatten() {
            if let Some(n) = r.name() {
                names.push(n.to_string());
            }
        }
    }
    names.sort();
    for n in names {
        if let Ok(r) = repo.find_reference(&n) {
            if let Ok(c) = r.peel_to_commit() {
                let t = c.time().seconds();
                let short = n.trim_start_matches("refs/tags/").to_string();
                match &best {
                    Some((bt, _)) if t <= *bt => {}
                    _ => best = Some((t, short)),
                }
            }
        }
    }
    best.map(|b| b.1).unwrap_or_default()
}

pub fn tags_and_branches(repo: &Repository) -> (usize, usize) {
    let mut tags = 0;
    let mut branches = 0;
    if let Ok(refs) = repo.references() {
        for r in refs.flatten() {
            let name = match r.name() {
                Some(n) => n.to_string(),
                None => continue,
            };
            if name.starts_with("refs/tags/") {
                tags += 1;
            } else if name.starts_with("refs/remotes/") && !name.ends_with("/HEAD") {
                branches += 1;
            }
        }
    }
    (tags, branches)
}

pub fn head_refs(repo: &Repository) -> Vec<String> {
    let mut refs = Vec::new();
    let head = match repo.find_reference("HEAD") {
        Ok(h) => h,
        Err(_) => return refs,
    };
    let target = match head.symbolic_target() {
        Some(t) => t.to_string(),
        None => return refs,
    };
    let short = shorten_ref(&target);
    refs.push(short.clone());
    if let Some(branch) = target.strip_prefix("refs/heads/") {
        if let Ok(cfg) = repo.config() {
            let remote = cfg.get_string(&format!("branch.{}.remote", branch)).ok();
            let merge = cfg.get_string(&format!("branch.{}.merge", branch)).ok();
            if let (Some(remote), Some(merge)) = (remote, merge) {
                let merge_short = shorten_ref(&merge);
                if merge_short == branch {
                    if let Ok(rem) = repo.find_remote(&remote) {
                        let src = format!("refs/heads/{}", branch);
                        let mut mapped: Option<String> = None;
                        for spec in rem.refspecs() {
                            if spec.direction() != git2::Direction::Fetch {
                                continue;
                            }
                            if spec.src_matches(&src) {
                                if let Ok(buf) = spec.transform(&src) {
                                    if let Some(s) = buf.as_str() {
                                        mapped = Some(s.to_string());
                                        break;
                                    }
                                }
                            }
                        }
                        if let Some(m) = mapped {
                            refs.push(shorten_ref(&m));
                        }
                    }
                }
            }
        }
    }
    refs
}

pub fn shorten_ref(name: &str) -> String {
    for p in ["refs/heads/", "refs/tags/", "refs/remotes/", "refs/"] {
        if let Some(s) = name.strip_prefix(p) {
            return s.to_string();
        }
    }
    name.to_string()
}

pub fn committer_name(repo: &Repository) -> String {
    let cfg = repo.config().ok();
    let get = |k: &str| -> Option<String> { cfg.as_ref().and_then(|c| c.get_string(k).ok()) };
    let env = |k: &str| -> Option<String> { std::env::var(k).ok() };
    let name = env("GIT_COMMITTER_NAME").or_else(|| get("committer.name")).or_else(|| get("user.name"));
    let email = env("GIT_COMMITTER_EMAIL")
        .or_else(|| get("committer.email"))
        .or_else(|| get("user.email"))
        .or_else(|| env("EMAIL"));
    match (name, email) {
        (Some(n), Some(_)) => n,
        _ => String::new(),
    }
}

pub fn remote_url(repo: &Repository) -> Option<String> {
    let cfg = repo.config().ok()?;
    cfg.get_string("remote.origin.url").ok()
}
