{"command":"cd /workspace/src/tokei && cat > counter.rs <<'EOF'
//! Line classification engine (code / comments / blanks), modelled on the
//! behaviour observed from the reference implementation.

use super::syntax_table::{syntax_for, Family, Syntax};
use regex::bytes::Regex;
use std::sync::OnceLock;

#[derive(Default, Clone, Copy, Debug)]
pub struct Stats {
    pub code: usize,
    pub comments: usize,
    pub blanks: usize,
}

impl Stats {
    fn add(&mut self, o: &Stats) {
        self.code += o.code;
        self.comments += o.comments;
        self.blanks += o.blanks;
    }
}

pub fn is_ws(c: u8) -> bool {
    c.is_ascii_whitespace()
}

pub fn trim(s: &[u8]) -> &[u8] {
    let start = match s.iter().position(|c| !is_ws(*c)) {
        Some(p) => p,
        None => return &[],
    };
    let end = s.iter().rposition(|c| !is_ws(*c)).unwrap_or(s.len() - 1);
    &s[start..=end]
}

pub fn trim_start(s: &[u8]) -> &[u8] {
    match s.iter().position(|c| !is_ws(*c)) {
        Some(p) => &s[p..],
        None => &[],
    }
}

fn contains(hay: &[u8], needle: &[u8]) -> bool {
    if needle.is_empty() {
        return true;
    }
    hay.windows(needle.len()).any(|w| w == needle)
}

fn find(hay: &[u8], needle: &[u8]) -> Option<usize> {
    if needle.is_empty() || needle.len() > hay.len() {
        return None;
    }
    hay.windows(needle.len()).position(|w| w == needle)
}

pub struct Shared {
    pub variant: &'static str,
    pub syn: Syntax,
    pub important: Vec<&'static str>,
    pub any_multi: Vec<(&'static str, &'static str)>,
}

impl Shared {
    pub fn new(variant: &'static str) -> Shared {
        let syn = syntax_for(variant);
        let mut important: Vec<&'static str> = syn.important.to_vec();
        for (s, _) in syn.quotes.iter().chain(syn.doc.iter()).chain(syn.verbatim.iter()) {
            important.push(s);
        }
        for (s, _) in syn.multi.iter().chain(syn.nested_comments.iter()) {
            important.push(s);
        }
        let mut any_multi: Vec<(&'static str, &'static str)> = syn.multi.to_vec();
        any_multi.extend_from_slice(syn.nested_comments);
        Shared { variant, syn, important, any_multi }
    }
}

struct Counter<'a> {
    sh: &'a Shared,
    quote: Option<&'static str>,
    quote_is_doc: bool,
    quote_is_verbatim: bool,
    stack: Vec<&'static str>,
}

enum Analysis {
    Normal,
    Child { end: usize, stats: Stats, extra_code: usize },
}

fn md_start_re() -> &'static Regex {
    static R: OnceLock<Regex> = OnceLock::new();
    R.get_or_init(|| Regex::new(r"```\S+\s").unwrap())
}
fn md_end_re() -> &'static Regex {
    static R: OnceLock<Regex> = OnceLock::new();
    R.get_or_init(|| Regex::new(r"```\s?").unwrap())
}

/// Iterates over lines; yields (start, end) where `end` includes the newline.
fn next_line(text: &[u8], pos: usize) -> Option<(usize, usize)> {
    if pos >= text.len() {
        return None;
    }
    match text[pos..].iter().position(|&c| c == b'\n') {
        Some(i) => Some((pos, pos + i + 1)),
        None => Some((pos, text.len())),
    }
}

impl<'a> Counter<'a> {
    fn new(sh: &'a Shared) -> Self {
        Counter { sh, quote: None, quote_is_doc: false, quote_is_verbatim: false, stack: Vec::new() }
    }

    fn is_plain_mode(&self) -> bool {
        self.quote.is_none() && self.stack.is_empty()
    }

    fn try_single_line(&self, line: &[u8], stats: &mut Stats) -> bool {
        if !self.is_plain_mode() {
            return false;
        }
        if trim(line).is_empty() {
            stats.blanks += 1;
            return true;
        }
        if self.sh.important.iter().any(|p| contains(line, p.as_bytes())) {
            return false;
        }
        if self.sh.syn.literate || self.sh.syn.line.iter().any(|c| line.starts_with(c.as_bytes())) {
            stats.comments += 1;
        } else {
            stats.code += 1;
        }
        true
    }

    fn parse_end_of_quote(&mut self, window: &[u8]) -> Option<usize> {
        if let Some(q) = self.quote {
            if window.starts_with(q.as_bytes()) {
                self.quote = None;
                return Some(q.len());
            }
        }
        if !self.quote_is_verbatim && window.starts_with(b"\\\\") {
            return Some(2);
        }
        if !self.quote_is_verbatim
            && window.starts_with(b"\\")
            && self.sh.syn.quotes.iter().any(|(s, _)| window[1..].starts_with(s.as_bytes()))
        {
            return Some(2);
        }
        None
    }

    fn parse_end_of_multi_line(&mut self, window: &[u8]) -> Option<usize> {
        if let Some(last) = self.stack.last() {
            if window.starts_with(last.as_bytes()) {
                let l = last.len();
                self.stack.pop();
                return Some(l);
            }
        }
        None
    }

    fn parse_quote(&mut self, window: &[u8]) -> Option<usize> {
        if !self.stack.is_empty() {
            return None;
        }
        if let Some((s, e)) = self.sh.syn.doc.iter().find(|(s, _)| window.starts_with(s.as_bytes())) {
            self.quote = Some(e);
            self.quote_is_verbatim = false;
            self.quote_is_doc = true;
            return Some(s.len());
        }
        if let Some((s, e)) = self.sh.syn.verbatim.iter().find(|(s, _)| window.starts_with(s.as_bytes())) {
            self.quote = Some(e);
            self.quote_is_verbatim = true;
            self.quote_is_doc = false;
            return Some(s.len());
        }
        if let Some((s, e)) = self.sh.syn.quotes.iter().find(|(s, _)| window.starts_with(s.as_bytes())) {
            self.quote = Some(e);
            self.quote_is_verbatim = false;
            self.quote_is_doc = false;
            return Some(s.len());
        }
        None
    }

    fn parse_multi_line_comment(&mut self, window: &[u8]) -> Option<usize> {
        if self.quote.is_some() {
            return None;
        }
        let syn = &self.sh.syn;
        for &(start, end) in syn.multi.iter().chain(syn.nested_comments.iter()) {
            if window.starts_with(start.as_bytes()) {
                if self.stack.is_empty() || syn.allows_nested || syn.nested_comments.contains(&(start, end)) {
                    self.stack.push(end);
                }
                return Some(start.len());
            }
        }
        None
    }

    fn parse_line_comment(&self, window: &[u8]) -> bool {
        if self.quote.is_some() || !self.stack.is_empty() {
            return false;
        }
        self.sh.syn.line.iter().any(|c| window.starts_with(c.as_bytes()))
    }

    fn line_is_comment(&self, line: &[u8], started_in_comments: bool) -> bool {
        let trimmed = trim(line);
        if self.quote.is_some() {
            return false;
        }
        if started_in_comments {
            return true;
        }
        let whole = self.sh.syn.line.iter().any(|c| trimmed.starts_with(c.as_bytes()))
            || self
                .sh
                .any_multi
                .iter()
                .any(|(s, e)| trimmed.starts_with(s.as_bytes()) && trimmed.ends_with(e.as_bytes()));
        if whole {
            return true;
        }
        match self.stack.last() {
            Some(q) => self.sh.any_multi.iter().any(|(s, e)| e == q && trimmed.starts_with(s.as_bytes())),
            None => false,
        }
    }

    fn parse_context(&self, lines: &[u8], start: usize, end: usize) -> Option<Analysis> {
        if self.quote.is_some() || !self.stack.is_empty() {
            return None;
        }
        match self.sh.syn.family {
            Family::Markdown => {
                let seg = &lines[start..end];
                if !contains(seg, b"```") {
                    return None;
                }
                let m = md_start_re().find(seg)?;
                let open_start = start + m.start();
                let open_end = start + m.end();
                let _ = open_start;
                let start_of_code = open_end;
                let closing = md_end_re().find_at(lines, start_of_code);
                let (end_of_code, end_of_block, close_ticks) = match closing {
                    Some(c) => (c.start(), c.end(), c.as_bytes().iter().filter(|&&b| b == b'`').count()),
                    None => (lines.len(), lines.len(), 0),
                };
                let open_ticks = m.as_bytes().iter().filter(|&&b| b == b'`').count();
                let balanced = open_ticks == close_ticks;
                let ident = trim(&m.as_bytes()[3..]);
                let lang = ident
                    .split(|&b| b == b',')
                    .find_map(|s| super::lang_from_name(&String::from_utf8_lossy(s)))
                    .unwrap_or("Markdown");
                let code_slice = if end_of_code > start_of_code { &lines[start_of_code..end_of_code] } else { &[][..] };
                let stats = parse_by_variant(lang, trim(code_slice));
                Some(Analysis::Child { end: end_of_block, stats, extra_code: if balanced { 2 } else { 1 } })
            }
            Family::Rust => {
                let rest = trim_start(&lines[start..]);
                let syntax: &[u8] = if rest.starts_with(b"///") {
                    b"///"
                } else if rest.starts_with(b"//!") {
                    b"//!"
                } else {
                    return None;
                };
                let mut pos = start;
                let mut markdown: Vec<u8> = Vec::new();
                let mut end_of_block = lines.len();
                while let Some((ls, le)) = next_line(lines, pos) {
                    pos = le;
                    if trim_start(&lines[ls..]).starts_with(syntax) {
                        let line = trim_start(&lines[ls..le]);
                        let stripped = &line[3.min(line.len())..];
                        markdown.extend_from_slice(stripped);
                        end_of_block = le;
                    } else {
                        end_of_block = ls;
                        break;
                    }
                }
                let stats = parse_by_variant("Markdown", trim(&markdown));
                Some(Analysis::Child { end: end_of_block, stats, extra_code: 0 })
            }
            Family::Html => super::html::parse_html_context(lines, start, end),
            _ => None,
        }
    }

    fn multi_line_analysis(&mut self, lines: &[u8], start: usize, end: usize) -> Analysis {
        let mut skip = 0usize;
        for i in start..end {
            if skip != 0 {
                skip -= 1;
                continue;
            }
            let window = &lines[i..];
            if trim(window).is_empty() {
                break;
            }
            let is_end = match self.parse_end_of_quote(window) {
                Some(n) => Some(n),
                None => self.parse_end_of_multi_line(window),
            };
            if let Some(n) = is_end {
                skip = n - 1;
                continue;
            } else if self.quote.is_some() {
                continue;
            }
            if let Some(child) = self.parse_context(lines, i, end) {
                return child;
            }
            let is_start = match self.parse_quote(window) {
                Some(n) => Some(n),
                None => self.parse_multi_line_comment(window),
            };
            if let Some(n) = is_start {
                skip = n - 1;
                continue;
            }
            if self.parse_line_comment(window) {
                break;
            }
        }
        Analysis::Normal
    }

    fn parse_lines(&mut self, text: &[u8]) -> Stats {
        let mut stats = Stats::default();
        let mut pos = 0;
        while let Some((start, end)) = next_line(text, pos) {
            pos = end;
            let raw = &text[start..end];
            let line = if self.sh.syn.fortran { raw } else { trim(raw) };
            if self.try_single_line(line, &mut stats) {
                continue;
            }
            let started_in_comments = !self.stack.is_empty();
            match self.multi_line_analysis(text, start, end) {
                Analysis::Normal => {}
                Analysis::Child { end: cend, stats: child, extra_code } => {
                    stats.code += extra_code;
                    stats.add(&child);
                    pos = cend;
                    continue;
                }
            }
            if self.sh.syn.literate || self.line_is_comment(line, started_in_comments) {
                stats.comments += 1;
            } else {
                stats.code += 1;
            }
        }
        stats
    }
}

thread_local! {
    static SHARED_CACHE: std::cell::RefCell<std::collections::HashMap<&'static str, &'static Shared>> =
        std::cell::RefCell::new(std::collections::HashMap::new());
}

fn shared_for(variant: &'static str) -> &'static Shared {
    SHARED_CACHE.with(|c| {
        let mut m = c.borrow_mut();
        if let Some(s) = m.get(variant) {
            return *s;
        }
        let s: &'static Shared = Box::leak(Box::new(Shared::new(variant)));
        m.insert(variant, s);
        s
    })
}

/// Parses `text` as the given language; returned `code` includes embedded
/// (child) language code.
pub fn parse_by_variant(variant: &str, text: &[u8]) -> Stats {
    let v: &'static str = match crate::langs::by_variant(variant) {
        Some(i) => crate::langs::LANGS[i].variant,
        None => match super::extra_variant(variant) {
            Some(v) => v,
            None => "Markdown",
        },
    };
    if v == "Jupyter" {
        return super::jupyter::parse_jupyter(text);
    }
    let sh = shared_for(v);
    let mut c = Counter::new(sh);
    c.parse_lines(text)
}

#[allow(dead_code)]
pub fn find_bytes(hay: &[u8], needle: &[u8]) -> Option<usize> {
    find(hay, needle)
}
