//! Language detection from file names, extensions and shebangs.

use super::ext_data::EXTENSIONS;
use std::io::Read;
use std::path::Path;

pub fn from_extension(ext: &str) -> Option<&'static str> {
    let lower = ext.to_lowercase();
    EXTENSIONS
        .binary_search_by(|(e, _)| (*e).cmp(lower.as_str()))
        .ok()
        .map(|i| EXTENSIONS[i].1)
}

fn from_filename(name: &str) -> Option<&'static str> {
    match name.to_lowercase().as_str() {
        "makefile" | "gnumakefile" => Some("Makefile"),
        "cmakelists.txt" => Some("CMake"),
        "dockerfile" => Some("Dockerfile"),
        "init.el" => Some("Elisp"),
        "config.fish" => Some("Fish"),
        _ => None,
    }
}

fn from_shebang(path: &Path) -> Option<&'static str> {
    let mut f = std::fs::File::open(path).ok()?;
    let mut buf = [0u8; 128];
    let mut len = 0;
    while len < buf.len() {
        match f.read(&mut buf[len..]) {
            Ok(0) => break,
            Ok(n) => len += n,
            Err(_) => return None,
        }
    }
    let buf = &buf[..len];
    let first = buf.split(|&b| b == b'\n').next()?;
    let first = std::str::from_utf8(first).ok()?;
    let mut words = first.split_whitespace();
    match words.next() {
        Some("#!/bin/sh") => Some("Sh"),
        Some("#!/bin/bash") => Some("Bash"),
        Some("#!/bin/zsh") => Some("Zsh"),
        Some("#!/bin/fish") => Some("Fish"),
        Some("#!/usr/bin/perl") => Some("Perl"),
        Some("#!/usr/bin/perl6") => Some("Raku"),
        Some("#!/usr/bin/raku") => Some("Raku"),
        Some("#!/usr/bin/crystal") => Some("Crystal"),
        Some("#!/usr/bin/env") => {
            let w = words.next()?;
            const ENVS: &[(&str, &str)] = &[
                ("bash", "Bash"),
                ("crystal", "Crystal"),
                ("fish", "Fish"),
                ("groovy", "Groovy"),
                ("perl6", "Raku"),
                ("python", "Python"),
                ("racket", "Racket"),
                ("raku", "Raku"),
                ("ruby", "Ruby"),
                ("sh", "Sh"),
            ];
            ENVS.iter().find(|(e, _)| w.starts_with(e)).map(|(_, l)| *l)
        }
        _ => None,
    }
}

/// Mirrors Rust's `Path::extension` semantics.
fn extension_of(name: &str) -> Option<&str> {
    if name == ".." {
        return None;
    }
    match name.rfind('.') {
        None | Some(0) => None,
        Some(i) => Some(&name[i + 1..]),
    }
}

pub fn detect(path: &Path) -> Option<&'static str> {
    let name = path.file_name()?.to_string_lossy().into_owned();
    if let Some(l) = from_filename(&name) {
        return Some(l);
    }
    match extension_of(&name) {
        Some(ext) => from_extension(ext),
        None => from_shebang(path),
    }
}
