//! Embedded languages in HTML-like files (<script>, <style>, <template>).

use super::counter::{parse_by_variant, trim, Stats};
use regex::bytes::Regex;
use std::sync::OnceLock;

fn re(i: usize) -> &'static Regex {
    static R: OnceLock<Vec<Regex>> = OnceLock::new();
    &R.get_or_init(|| {
        vec![
            Regex::new(r#"<script(?:.*type="(.*)")?.*?>"#).unwrap(),
            Regex::new(r#"<style(?:.*lang="(.*)")?.*?>"#).unwrap(),
            Regex::new(r#"<template(?:.*lang="(.*)")?.*?>"#).unwrap(),
        ]
    })[i]
}

fn find_at(hay: &[u8], needle: &[u8], from: usize) -> Option<usize> {
    if from > hay.len() {
        return None;
    }
    hay[from..].windows(needle.len()).position(|w| w == needle).map(|p| p + from)
}

