pub mod html;
mod jupyter;
mod syntax_table;

use crate::langs::{LangType, LANGS};
use std::collections::HashMap;
use std::path::Path;
use std::sync::Mutex;

/// Case-insensitive match against language display names.
pub fn lang_from_name(name: &str) -> Option<&'static str> {
    let lower = name.to_lowercase();
    for l in LANGS {
        if l.display.to_lowercase() == lower {
            return Some(l.variant);
        }
    }
    match lower.as_str() {
        "awk" => Some("Awk"),
        _ => None,
    }
}

pub fn extra_variant(v: &str) -> Option<&'static str> {
    match v {
        "Awk" => Some("Awk"),
        _ => None,
    }
}

fn decode(bytes: Vec<u8>) -> Vec<u8> {
    if bytes.starts_with(&[0xEF, 0xBB, 0xBF]) {
        return bytes[3..].to_vec();
    }
    let utf16 = |le: bool| -> Vec<u8> {
        let body = &bytes[2..];
        let units: Vec<u16> = body
            .chunks(2)
            .map(|c| {
                if c.len() < 2 {
                    0xFFFD
                } else if le {
                    u16::from_le_bytes([c[0], c[1]])
                } else {
                    u16::from_be_bytes([c[0], c[1]])
                }
            })
            .collect();
        String::from_utf16_lossy(&units).into_bytes()
    };
    if bytes.starts_with(&[0xFF, 0xFE]) {
        return utf16(true);
    }
    if bytes.starts_with(&[0xFE, 0xFF]) {
        return utf16(false);
    }
    bytes
}

pub struct LanguageStats {
    /// (index into LANGS, lines of code)
    pub by_language: Vec<(usize, usize)>,
}

pub fn get_statistics(
    root: &Path,
    excluded: &[String],
    types: &[LangType],
    include_hidden: bool,
) -> LanguageStats {
    let mut walker = ignore::WalkBuilder::new(root);
    if !excluded.is_empty() {
        let mut ob = ignore::overrides::OverrideBuilder::new(".");
        for e in excluded {
            let _ = ob.add(&format!("!{}", e));
        }
        if let Ok(o) = ob.build() {
            walker.overrides(o);
        }
    }
    walker.add_custom_ignore_filename(".tokeignore");
    walker
        .git_exclude(true)
        .git_global(true)
        .git_ignore(true)
        .hidden(!include_hidden)
        .ignore(true)
        .parents(true);

    let totals: Mutex<HashMap<&'static str, usize>> = Mutex::new(HashMap::new());
    let seen: Mutex<HashMap<&'static str, bool>> = Mutex::new(HashMap::new());
    walker.build_parallel().run(|| {
        let totals = &totals;
        let seen = &seen;
        Box::new(move |entry| {
            let entry = match entry {
                Ok(e) => e,
                Err(_) => return ignore::WalkState::Continue,
            };
            if !entry.file_type().map_or(false, |ft| ft.is_file()) {
                return ignore::WalkState::Continue;
            }
            let path = entry.path();
            let variant = match detect::detect(path) {
                Some(v) => v,
                None => return ignore::WalkState::Continue,
            };
            let idx = match crate::langs::by_variant(variant) {
                Some(i) => i,
                None => return ignore::WalkState::Continue,
            };
            if !types.contains(&LANGS[idx].ltype) {
                return ignore::WalkState::Continue;
            }
            let bytes = match std::fs::read(path) {
                Ok(b) => decode(b),
                Err(_) => return ignore::WalkState::Continue,
            };
            let stats = counter::parse_by_variant(variant, &bytes);
            *totals.lock().unwrap().entry(LANGS[idx].variant).or_insert(0) += stats.code;
            seen.lock().unwrap().insert(LANGS[idx].variant, true);
            ignore::WalkState::Continue
        })
    });
    let totals = totals.into_inner().unwrap();
    let mut by_language: Vec<(usize, usize)> = totals
        .into_iter()
        .filter_map(|(v, n)| crate::langs::by_variant(v).map(|i| (i, n)))
        .collect();
    by_language.sort();
    LanguageStats { by_language }
}
