//! Formatting helpers: numbers, byte sizes and dates.

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum NumberSeparator {
    Plain,
    Comma,
    Space,
    Underscore,
}

impl NumberSeparator {
    pub fn from_str(s: &str) -> NumberSeparator {
        match s {
            "comma" => NumberSeparator::Comma,
            "space" => NumberSeparator::Space,
            "underscore" => NumberSeparator::Underscore,
            _ => NumberSeparator::Plain,
        }
    }
    pub fn format(&self, n: usize) -> String {
        let sep = match self {
            NumberSeparator::Plain => return n.to_string(),
            NumberSeparator::Comma => ",",
            NumberSeparator::Space => "\u{202f}",
            NumberSeparator::Underscore => "_",
        };
        let digits = n.to_string();
        let mut out = String::new();
        let len = digits.len();
        for (i, c) in digits.chars().enumerate() {
            if i > 0 && (len - i) % 3 == 0 {
                out.push_str(sep);
            }
            out.push(c);
        }
        out
    }
}

pub fn format_bytes(bytes: u64) -> String {
    const UNITS: [&str; 7] = ["B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB"];
    if bytes < 1024 {
        return format!("{} B", bytes);
    }
    let mut unit = 0;
    let mut div: f64 = 1.0;
    while unit + 1 < UNITS.len() && (bytes as f64) >= div * 1024.0 {
        div *= 1024.0;
        unit += 1;
    }
    let v = bytes as f64 / div;
    let rounded = (v * 100.0).round() / 100.0;
    format!("{} {}", rounded, UNITS[unit])
}

const MINUTE: i64 = 60;
const HOUR: i64 = 60 * MINUTE;
const DAY: i64 = 24 * HOUR;
const WEEK: i64 = 7 * DAY;
const MONTH: i64 = 30 * DAY;
const YEAR: i64 = 365 * DAY;

/// `delta` = time - now (negative means in the past).
pub fn humanize(delta: i64) -> String {
    let n = delta.abs();
    let text = if n > 547 * DAY {
        plural(std::cmp::max(n / YEAR, 2), "year")
    } else if n > 345 * DAY {
        "a year".to_string()
    } else if n > 45 * DAY {
        plural(std::cmp::max(n / MONTH, 2), "month")
    } else if n > 29 * DAY {
        "a month".to_string()
    } else if n > 10 * DAY + 12 * HOUR {
        plural(std::cmp::max(n / WEEK, 2), "week")
    } else if n > 6 * DAY + 12 * HOUR {
        "a week".to_string()
    } else if n > 36 * HOUR {
        plural(std::cmp::max(n / DAY, 2), "day")
    } else if n > 22 * HOUR {
        "a day".to_string()
    } else if n > 90 * MINUTE {
        plural(std::cmp::max(n / HOUR, 2), "hour")
    } else if n > 45 * MINUTE {
        "an hour".to_string()
