//! Package manifest detection (Cargo, npm).

use std::path::Path;

#[derive(Clone, Debug)]
pub struct Manifest {
    pub manager: &'static str,
    pub number_of_dependencies: usize,
    #[allow(dead_code)]
    pub name: String,
    pub description: Option<String>,
    pub version: String,
    pub license: Option<String>,
}

fn opt_string(v: Option<&toml::Value>) -> Result<Option<String>, ()> {
    match v {
        None => Ok(None),
        Some(toml::Value::String(s)) => Ok(Some(s.clone())),
        Some(_) => Err(()),
    }
}

fn parse_cargo(path: &Path) -> Option<Manifest> {
    let text = std::fs::read_to_string(path).ok()?;
    let value: toml::Table = text.parse().ok()?;
    let package = value.get("package")?.as_table()?;
    let name = match package.get("name") {
        Some(toml::Value::String(s)) => s.clone(),
        _ => return None,
    };
    let version = opt_string(package.get("version")).ok()?.unwrap_or_else(|| "0.0.0".to_string());
    let description = opt_string(package.get("description")).ok()?;
    let license = opt_string(package.get("license")).ok()?;
    let deps = match value.get("dependencies") {
        None => 0,
        Some(toml::Value::Table(t)) => t.len(),
        Some(_) => return None,
    };
    Some(Manifest { manager: "Cargo", number_of_dependencies: deps, name, description, version, license })
}

fn parse_npm(path: &Path) -> Option<Manifest> {
    let text = std::fs::read(path).ok()?;
    let v: serde_json::Value = serde_json::from_slice(&text).ok()?;
    let obj = v.as_object()?;
    let name = obj.get("name")?.as_str()?.to_string();
    let version = obj.get("version")?.as_str()?.to_string();
    let opt = |k: &str| -> Result<Option<String>, ()> {
        match obj.get(k) {
            None | Some(serde_json::Value::Null) => Ok(None),
            Some(serde_json::Value::String(s)) => Ok(Some(s.clone())),
            Some(_) => Err(()),
        }
    };
    let description = opt("description").ok()?;
    let license = opt("license").ok()?;
    let deps = match obj.get("dependencies") {
        None | Some(serde_json::Value::Null) => 0,
        Some(serde_json::Value::Object(m)) => {
            if m.values().any(|x| !x.is_string()) {
                return None;
            }
            m.len()
        }
        Some(_) => return None,
    };
    Some(Manifest { manager: "Npm", number_of_dependencies: deps, name, description, version, license })
}

pub fn get_manifest(dir: &Path) -> Option<Manifest> {
    let cargo = dir.join("Cargo.toml");
    if cargo.is_file() {
        if let Some(m) = parse_cargo(&cargo) {
            return Some(m);
        }
    }
    let npm = dir.join("package.json");
    if npm.is_file() {
        if let Some(m) = parse_npm(&npm) {
            return Some(m);
        }
    }
    None
}
