            continue;
        }
        if chars[i] == ' ' {
            out.push(Token::Space);
        } else {
            out.push(Token::Char(chars[i]));
        }
        i += 1;
    }
    out
}

fn is_empty(tokens: &[Token]) -> bool {
    !tokens.iter().any(|t| t.is_solid())
}

fn true_length(tokens: &[Token]) -> usize {
    let mut last_non_space = 0;
    let mut last = 0;
    for t in tokens {
        if t.has_zero_width() {
            continue;
        }
        last += 1;
        if !t.is_space() {
            last_non_space = last;
        }
    }
    last_non_space
}

fn leading_spaces(tokens: &[Token]) -> usize {
    tokens.iter().take_while(|t| !t.is_solid()).filter(|t| t.is_space()).count()
}

pub struct AsciiArt {
    lines: Vec<Vec<Token>>,
    colors: Vec<DynColor>,
    bold: bool,
    start: usize,
    end: usize,
    pos: usize,
}

impl AsciiArt {
    pub fn new(input: &str, colors: &[DynColor], bold: bool) -> AsciiArt {
        let mut lines: Vec<&str> = input.lines().skip_while(|l| l.is_empty()).collect();
        while let Some(last) = lines.last() {
            if is_empty(&tokenize(last)) {
                lines.pop();
            } else {
                break;
            }
        }
        let lines: Vec<Vec<Token>> = lines.iter().map(|l| tokenize(l)).collect();
        let start = lines.iter().map(|l| leading_spaces(l)).min().unwrap_or(usize::MAX);
        let end = lines.iter().map(|l| true_length(l)).max().unwrap_or(0);
        AsciiArt { lines, colors: colors.to_vec(), bold, start, end, pos: 0 }
    }

    pub fn width(&self) -> usize {
        self.end.saturating_sub(self.start)
    }

    fn render(&self, tokens: &[Token]) -> String {
        let mut width = self.end.saturating_sub(self.start);
        let mut whole = String::new();
        let mut segment = String::new();
        let mut color = DynColor::DEFAULT;
        // truncate
        let mut skip = self.start;
        let mut remaining = width;
        let mut kept: Vec<Token> = Vec::new();
        for t in tokens {
            if skip > 0 && !t.has_zero_width() {
                skip -= 1;
                continue;
            }
            if remaining == 0 {
                break;
            }
            if !t.has_zero_width() {
                remaining -= 1;
            }
            kept.push(*t);
        }
        for t in kept {
            match t {
                Token::Char(c) => {
                    width = width.saturating_sub(1);
                    segment.push(c);
                }
                Token::Space => {
                    width = width.saturating_sub(1);
                    segment.push(' ');
                }
                Token::Color(n) => {
                    whole.push_str(&styled(&segment, color, self.bold));
                    segment.clear();
                    color = self.colors.get(n as usize).copied().unwrap_or(DynColor::DEFAULT);
                }
            }
        }
        whole.push_str(&styled(&segment, color, self.bold));
        for _ in 0..width {
            whole.push(' ');
        }
        whole
    }
}

impl Iterator for AsciiArt {
    type Item = String;
    fn next(&mut self) -> Option<String> {
        if self.pos >= self.lines.len() {
            return None;
        }
        let l = self.lines[self.pos].clone();
        self.pos += 1;
        Some(self.render(&l))
    }
}
