    Color(u32),
    Char(char),
    Space,
}

impl Token {
    fn is_solid(&self) -> bool {
        matches!(self, Token::Char(_))
    }
    fn is_space(&self) -> bool {
        matches!(self, Token::Space)
    }
    fn has_zero_width(&self) -> bool {
        matches!(self, Token::Color(_))
    }
}

fn tokenize(line: &str) -> Vec<Token> {
    let chars: Vec<char> = line.chars().collect();
    let mut out = Vec::new();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '{' && i + 2 < chars.len() && chars[i + 1].is_ascii_digit() && chars[i + 2] == '}' {
            out.push(Token::Color(chars[i + 1].to_digit(10).unwrap()));
            i += 3;
            continue;
        }
        if chars[i] == ' ' {
            out.push(Token::Space);
        } else {
            out.push(Token::Char(chars[i]));
        }
        i += 1;
    }
    out
}

