cd /workspace/src && cat > info.rs <<'EOF'
//! Collection of repository information and its textual rendering.

use crate::color::{bg, fg, styled, DynColor};
use crate::fmt::NumberSeparator;
use crate::git::Author;
use crate::langs::LANGS;
use serde::Serialize;

#[derive(Clone, Copy)]
pub struct TextColors {
    pub title: DynColor,
    pub tilde: DynColor,
    pub underline: DynColor,
    pub subtitle: DynColor,
    pub colon: DynColor,
    pub info: DynColor,
}

impl TextColors {
    pub fn new(custom: &[u8], logo_primary: DynColor) -> TextColors {
        let c = |i: usize, d: DynColor| custom.get(i).map(|n| DynColor::from_num(*n)).unwrap_or(d);
        TextColors {
            title: c(0, logo_primary),
            tilde: c(1, DynColor::DEFAULT),
            underline: c(2, DynColor::DEFAULT),
            subtitle: c(3, logo_primary),
            colon: c(4, DynColor::DEFAULT),
            info: c(5, DynColor::DEFAULT),
        }
    }
}

pub struct Title {
    pub git_username: String,
    pub git_version: String,
}

pub enum InfoField {
    Project { repo_name: String, branches: usize, tags: usize },
    Description(Option<String>),
    Head { short_id: String, refs: Vec<String> },
    Pending { added: usize, deleted: usize, modified: usize },
    Version(String),
    Created(String),
    Languages(Vec<(usize, f64)>),
    Dependencies(String),
    Authors(Vec<Author>),
    LastChange(String),
    Contributors { total: usize },
    Url(String),
    Commits { count: usize, shallow: bool },
    Churn { churns: Vec<(String, usize)>, pool: usize },
    Loc(usize),
    Size { size: String, count: usize },
    License(String),
}

pub struct Info {
    pub title: Option<Title>,
    pub fields: Vec<InfoField>,
    pub text_colors: TextColors,
    pub no_bold: bool,
    pub no_color_palette: bool,
    pub number_separator: NumberSeparator,
    pub number_of_languages: usize,
    pub number_of_authors: usize,
    pub true_color: bool,
    pub nerd_fonts: bool,
    pub show_email: bool,
}

const LANGUAGES_BAR_LENGTH: usize = 26;

fn shorten_path(p: &str) -> String {
    let parts: Vec<&str> = p.split('/').collect();
    if parts.len() > 2 {
        format!("\u{2026}/{}", parts[parts.len() - 2..].join("/"))
    } else {
        p.to_string()
    }
}

impl Info {
    fn fmt_num(&self, n: usize) -> String {
        self.number_separator.format(n)
    }

    /// Returns (title, value) of a field, or None if it should not be displayed.
    fn field_text(&self, f: &InfoField) -> Option<(String, String)> {
        match f {
            InfoField::Project { repo_name, branches, tags } => {
                if repo_name.is_empty() {
                    return None;
                }
                let b = match branches {
                    0 => String::new(),
                    1 => "1 branch".to_string(),
                    n => format!("{} branches", self.fmt_num(*n)),
                };
                let t = match tags {
                    0 => String::new(),
                    1 => "1 tag".to_string(),
                    n => format!("{} tags", self.fmt_num(*n)),
                };
                let v = if b.is_empty() && t.is_empty() {
                    repo_name.clone()
                } else if b.is_empty() || t.is_empty() {
                    format!("{} ({}{})", repo_name, b, t)
                } else {
                    format!("{} ({}, {})", repo_name, b, t)
                };
                Some(("Project".into(), v))
            }
            InfoField::Description(d) => {
                let d = d.as_ref()?;
                let words: Vec<&str> = d.split_whitespace().collect();
                if words.is_empty() {
                    return None;
                }
                let title = "Description";
                let pad = " ".repeat(title.len() + 2);
                let mut v = String::new();
                for (i, chunk) in words.chunks(5).enumerate() {
                    if i > 0 {
                        v.push('\n');
                        v.push_str(&pad);
                    }
                    v.push_str(&chunk.join(" "));
                }
                Some((title.into(), v))
            }
            InfoField::Head { short_id, refs } => {
                let v = if refs.is_empty() { short_id.clone() } else { format!("{} ({})", short_id, refs.join(", ")) };
                Some(("HEAD".into(), v))
            }
            InfoField::Pending { added, deleted, modified } => {
                let mut parts = Vec::new();
                if *modified > 0 {
                    parts.push(format!("{}+-", self.fmt_num(*modified)));
                }
                if *added > 0 {
                    parts.push(format!("{}+", self.fmt_num(*added)));
                }
                if *deleted > 0 {
                    parts.push(format!("{}-", self.fmt_num(*deleted)));
                }
                if parts.is_empty() {
                    return None;
                }
                Some(("Pending".into(), parts.join(" ")))
            }
            InfoField::Version(v) => {
                if v.is_empty() {
                    return None;
                }
                Some(("Version".into(), v.clone()))
            }
            InfoField::Created(v) => {
                if v.is_empty() {
                    return None;
                }
                Some(("Created".into(), v.clone()))
            }
            InfoField::Languages(langs) => {
                if langs.is_empty() {
                    return None;
                }
                let palette = [
                    DynColor::RED,
                    DynColor::GREEN,
                    DynColor::YELLOW,
                    DynColor::BLUE,
                    DynColor::MAGENTA,
                    DynColor::CYAN,
                ];
                let mut entries: Vec<(String, f64, DynColor, &str)> = Vec::new();
                for (i, (idx, pct)) in langs.iter().enumerate() {
                    if i >= self.number_of_languages {
                        break;
                    }
                    let l = &LANGS[*idx];
                    let c = if self.true_color { l.chip_color() } else { palette[i % palette.len()] };
                    entries.push((l.display.to_string(), *pct, c, l.nerd));
                }
                if langs.len() > self.number_of_languages {
                    let other: f64 = langs[self.number_of_languages..].iter().map(|x| x.1).sum();
                    entries.push(("Other".to_string(), other, DynColor::WHITE, "\u{25cf}"));
                }
                let title = if entries.len() > 1 { "Languages" } else { "Language" };
                let pad = " ".repeat(title.len() + 2);
                let mut bar = String::new();
                for (_, pct, c, _) in &entries {
                    let w = std::cmp::max((pct / 100.0 * LANGUAGES_BAR_LENGTH as f64).round() as usize, 1);
                    bar.push_str(&bg(&" ".repeat(w), *c));
                }
                let mut field = String::new();
                for (i, (name, pct, c, nerd)) in entries.iter().enumerate() {
                    let chip = if self.nerd_fonts { *nerd } else { "\u{25cf}" };
                    let s = format!(
                        "{} {} ",
                        fg(chip, *c),
                        fg(&format!("{} ({:.1} %)", name, pct), self.text_colors.info)
                    );
                    if i % 2 == 0 {
                        field.push('\n');
                        field.push_str(&pad);
                        field.push_str(&s);
                    } else {
                        field.push_str(s.trim_end());
                    }
                }
                Some((title.into(), format!("{}{}", bar, field)))
            }
            InfoField::Dependencies(d) => {
                if d.is_empty() {
                    return None;
                }
                Some(("Dependencies".into(), d.clone()))
            }
            InfoField::Authors(authors) => {
                if authors.is_empty() {
                    return None;
                }
                let title = if authors.len() > 1 { "Authors" } else { "Author" };
                let pad = " ".repeat(title.len() + 2);
                let width = authors.iter().map(|a| a.contribution.to_string().len()).max().unwrap_or(1);
                let mut v = String::new();
                for (i, a) in authors.iter().enumerate() {
                    if i > 0 {
                        v.push('\n');
                        v.push_str(&pad);
                    }
                    let commits = self.fmt_num(a.nbr_of_commits);
                    if self.show_email {
                        v.push_str(&format!("{:>w$}% {} <{}> {}", a.contribution, a.name, a.email, commits, w = width));
                    } else {
                        v.push_str(&format!("{:>w$}% {} {}", a.contribution, a.name, commits, w = width));
                    }
                }
                Some((title.into(), v))
            }
            InfoField::LastChange(v) => {
                if v.is_empty() {
                    return None;
                }
                Some(("Last change".into(), v.clone()))
            }
            InfoField::Contributors { total } => {
                if *total <= self.number_of_authors {
                    return None;
                }
                Some(("Contributors".into(), self.fmt_num(*total)))
            }
            InfoField::Url(u) => {
                if u.is_empty() {
                    return None;
                }
                Some(("URL".into(), u.clone()))
            }
            InfoField::Commits { count, shallow } => {
                let v = format!("{}{}", self.fmt_num(*count), if *shallow { " (shallow)" } else { "" });
                Some(("Commits".into(), v))
            }
            InfoField::Churn { churns, pool } => {
                if churns.is_empty() {
                    return None;
                }
                let title = format!("Churn ({})", pool);
                let pad = " ".repeat(title.len() + 2);
                let mut v = String::new();
                for (i, (p, n)) in churns.iter().enumerate() {
                    if i > 0 {
                        v.push('\n');
                        v.push_str(&pad);
                    }
                    v.push_str(&format!("{} {}", shorten_path(p), self.fmt_num(*n)));
                }
                Some((title, v))
            }
            InfoField::Loc(n) => Some(("Lines of code".into(), self.fmt_num(*n))),
            InfoField::Size { size, count } => {
                let v = match count {
                    0 => size.clone(),
                    1 => format!("{} (1 file)", size),
                    n => format!("{} ({} files)", size, self.fmt_num(*n)),
                };
                Some(("Size".into(), v))
            }
            InfoField::License(l) => {
                if l.is_empty() {
                    return None;
                }
                Some(("License".into(), l.clone()))
            }
        }
    }

    pub fn render(&self) -> String {
        let bold = !self.no_bold;
        let tc = &self.text_colors;
        let mut out = String::new();
        if let Some(t) = &self.title {
            if !t.git_username.is_empty() || !t.git_version.is_empty() {
                let user = styled(&t.git_username, tc.title, bold);
                let ver = styled(&t.git_version, tc.title, bold);
                let len;
                if !t.git_username.is_empty() && !t.git_version.is_empty() {
                    let tilde = styled("~", tc.tilde, bold);
                    out.push_str(&format!("{} {} {}\n", user, tilde, ver));
                    len = t.git_username.len() + 3 + t.git_version.len();
                } else {
                    out.push_str(&format!("{}{}\n", user, ver));
                    len = t.git_username.len() + t.git_version.len();
                }
                out.push_str(&fg(&"-".repeat(len), tc.underline));
                out.push('\n');
            }
        }
        for f in &self.fields {
            if let Some((title, value)) = self.field_text(f) {
                let mut lines = value.split('\n');
                let first = lines.next().unwrap_or("");
                out.push_str(&format!(
                    "{}{} {}\n",
                    styled(&title, tc.subtitle, bold),
                    styled(":", tc.colon, bold),
                    styled(first, tc.info, false)
                ));
                for l in lines {
                    out.push_str(&styled(l, tc.info, false));
                    out.push('\n');
                }
            }
        }
        if !self.no_color_palette {
            out.push('\n');
            for c in 40..48u8 {
                out.push_str(&format!("\x1b[{}m   \x1b[49m", c));
            }
            out.push('\n');
        }
        out
    }

    pub fn to_json_value(&self) -> JsonOut {
        let title = self.title.as_ref().map(|t| JsonTitle {
            git_username: t.git_username.clone(),
            git_version: t.git_version.clone(),
        });
        let mut fields = Vec::new();
        for f in &self.fields {
            let jf = match f {
                InfoField::Project { repo_name, branches, tags } => JsonField::ProjectInfo {
                    repo_name: repo_name.clone(),
                    number_of_branches: *branches,
                    number_of_tags: *tags,
                },
                InfoField::Description(d) => JsonField::DescriptionInfo { description: d.clone() },
                InfoField::Head { short_id, refs } => JsonField::HeadInfo {
                    head_refs: JsonHeadRefs { short_commit_id: short_id.clone(), refs: refs.clone() },
                },
                InfoField::Pending { added, deleted, modified } => {
                    JsonField::PendingInfo { added: *added, deleted: *deleted, modified: *modified }
                }
                InfoField::Version(v) => JsonField::VersionInfo { version: v.clone() },
                InfoField::Created(v) => JsonField::CreatedInfo { creation_date: v.clone() },
                InfoField::Languages(l) => JsonField::LanguagesInfo {
                    languages_with_percentage: l
                        .iter()
                        .map(|(i, p)| JsonLang { language: LANGS[*i].variant.to_string(), percentage: *p })
                        .collect(),
                },
                InfoField::Dependencies(d) => JsonField::DependenciesInfo { dependencies: d.clone() },
                InfoField::Authors(a) => JsonField::AuthorsInfo {
                    authors: a
                        .iter()
                        .map(|a| JsonAuthor {
                            name: a.name.clone(),
                            email: if self.show_email { Some(a.email.clone()) } else { None },
                            nbr_of_commits: a.nbr_of_commits,
                            contribution: a.contribution,
                        })
                        .collect(),
                },
                InfoField::LastChange(v) => JsonField::LastChangeInfo { last_change: v.clone() },
                InfoField::Contributors { total } => JsonField::ContributorsInfo { total_number_of_authors: *total },
                InfoField::Url(u) => JsonField::UrlInfo { repo_url: u.clone() },
                InfoField::Commits { count, shallow } => {
                    JsonField::CommitsInfo { number_of_commits: *count, is_shallow: *shallow }
                }
                InfoField::Churn { churns, pool } => JsonField::ChurnInfo {
                    file_churns: churns
                        .iter()
                        .map(|(p, n)| JsonChurn { file_path: p.clone(), nbr_of_commits: *n })
                        .collect(),
                    churn_pool_size: *pool,
                },
                InfoField::Loc(n) => JsonField::LocInfo { lines_of_code: *n },
                InfoField::Size { size, count } => JsonField::SizeInfo { repo_size: size.clone(), file_count: *count },
                InfoField::License(l) => JsonField::LicenseInfo { license: l.clone() },
            };
            fields.push(jf);
        }
        JsonOut { title, info_fields: fields }
    }
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
