{"command":"cd /workspace/src && cat > main.rs <<'EOF'
mod ascii;
mod cli;
mod color;
mod fmt;
mod git;
mod info;
mod langs;
mod langs_data;
mod license;
mod manifest;
mod panic;
mod printer;
mod tokei;
mod url;

use color::DynColor;
use info::{Info, InfoField, TextColors, Title};
use langs::{LangType, LANGS};
use std::path::{Path, PathBuf};

fn fail(msg: &str) -> ! {
    eprintln!("Error: {}", msg);
    std::process::exit(1);
}

fn git_version() -> String {
    match std::process::Command::new("git").arg("--version").output() {
        Ok(o) => String::from_utf8_lossy(&o.stdout).trim_end_matches('\n').trim_end_matches('\r').to_string(),
        Err(_) => String::new(),
    }
}

/// Computes the path of the work tree the way it is seen from the input path
/// (relative inputs give relative work tree paths).
fn workdir_path(input: &Path, workdir: &Path) -> PathBuf {
    if input.is_absolute() {
        return workdir.to_path_buf();
    }
    let abs_input = match std::fs::canonicalize(input) {
        Ok(p) => p,
        Err(_) => return workdir.to_path_buf(),
    };
    let wd = match std::fs::canonicalize(workdir) {
        Ok(p) => p,
        Err(_) => return workdir.to_path_buf(),
    };
    if abs_input == wd {
        return input.to_path_buf();
    }
    let mut p = input.to_path_buf();
    let mut cur = abs_input.as_path();
    while cur != wd {
        match cur.parent() {
            Some(par) => {
                p.push("..");
                cur = par;
            }
            None => return workdir.to_path_buf(),
        }
    }
    p
}

fn main() {
    panic::install();
    let mut cmd = cli::build();
    let m = cmd.clone().get_matches();

    if m.get_flag("languages") {
        let mut s = String::new();
        for l in LANGS {
            s.push_str(l.display);
            s.push('\n');
        }
        print!("{}", s);
        return;
    }
    if m.get_flag("package-managers") {
        print!("Npm\nCargo\n");
        return;
    }
    if let Some(sh) = m.get_one::<String>("generate") {
        let shell = match sh.as_str() {
            "bash" => clap_complete::Shell::Bash,
            "elvish" => clap_complete::Shell::Elvish,
            "fish" => clap_complete::Shell::Fish,
            "powershell" => clap_complete::Shell::PowerShell,
            _ => clap_complete::Shell::Zsh,
        };
        let mut buf: Vec<u8> = Vec::new();
        clap_complete::generate(shell, &mut cmd, "onefetch", &mut buf);
        let mut s = String::from_utf8_lossy(&buf).into_owned();
        if sh == "zsh" {
            s = s.replace("override the default pattern]::REGEX:_default'", "override the default pattern]'");
        }
        print!("{}", s);
        return;
    }

    let input: PathBuf = m.get_one::<PathBuf>("input").cloned().unwrap_or_else(|| PathBuf::from("."));
    if !input.is_dir() {
        fail(&format!("Failed to access a directory, or path is not a directory: '{}'", input.display()));
    }

    let image = m.get_one::<PathBuf>("image").cloned();
    let image_data = image.as_ref().map(|p| match printer::load_image(p) {
        Ok(img) => img,
        Err(e) => {
            eprintln!("Error: Could not load the image file at '{}'\n\nCaused by:\n    {}", p.display(), e);
            std::process::exit(1);
        }
    });

    let repo = match git2::Repository::discover(&input) {
        Ok(r) if !r.is_bare() && r.workdir().is_some() => r,
        _ => fail(&format!("Could not find a git repository in '{}' or in any of its parents", input.display())),
    };
    let workdir_abs = repo.workdir().unwrap().to_path_buf();
    let workdir = workdir_path(&input, &workdir_abs);

    let head_oid = match repo.head() {
        Ok(h) => match h.target() {
            Some(o) => o,
            None => fail("Failed to traverse Git commit history"),
        },
        Err(_) => {
            let branch = repo
                .find_reference("HEAD")
                .ok()
                .and_then(|r| r.symbolic_target().map(|s| s.to_string()))
                .unwrap_or_else(|| "HEAD".to_string());
            eprintln!(
                "Error: Failed to traverse Git commit history\n\nCaused by:\n    Branch '{}' does not have any commits",
                branch
            );
            std::process::exit(1);
        }
    };

    let disabled: Vec<String> = m.get_many::<String>("disabled-fields").map(|v| v.cloned().collect()).unwrap_or_default();
    let is_disabled = |f: &str| disabled.iter().any(|d| d == f);
    let number_of_authors = *m.get_one::<usize>("number-of-authors").unwrap();
    let number_of_languages = *m.get_one::<usize>("number-of-languages").unwrap();
    let number_of_file_churns = *m.get_one::<usize>("number-of-file-churns").unwrap();
    let churn_pool_size = m.get_one::<usize>("churn-pool-size").copied();
    let excluded: Vec<String> = m.get_many::<String>("exclude").map(|v| v.cloned().collect()).unwrap_or_default();
    let no_bots: Option<regex::Regex> = if m.contains_id("no-bots") && m.value_source("no-bots") == Some(clap::parser::ValueSource::CommandLine) {
        match m.get_one::<String>("no-bots") {
            Some(r) => Some(regex::Regex::new(r).unwrap()),
            None => Some(git::default_bot_regex()),
        }
    } else {
        None
    };
    let no_merges = m.get_flag("no-merges");
    let show_email = m.get_flag("email");
    let http_url = m.get_flag("http-url");
    let hide_token = m.get_flag("hide-token");
    let include_hidden = m.get_flag("include-hidden");
    let mut types: Vec<LangType> = Vec::new();
    for t in m.get_many::<String>("type").unwrap() {
        types.push(match t.as_str() {
            "programming" => LangType::Programming,
            "markup" => LangType::Markup,
            "prose" => LangType::Prose,
            _ => LangType::Data,
        });
    }
    let text_colors_arg: Vec<u8> = m.get_many::<u8>("text-colors").map(|v| v.copied().collect()).unwrap_or_default();
    let iso_time = m.get_flag("iso-time");
    let number_separator = fmt::NumberSeparator::from_str(m.get_one::<String>("number-separator").unwrap());
    let no_bold = m.get_flag("no-bold");
    let ascii_input = m.get_one::<String>("ascii-input").cloned();
    let ascii_colors: Vec<u8> = m.get_many::<u8>("ascii-colors").map(|v| v.copied().collect()).unwrap_or_default();
    let ascii_language = m.get_one::<String>("ascii-language").and_then(|a| langs::by_arg(a));
    let true_color = match m.get_one::<String>("true-color").map(|s| s.as_str()) {
        Some("always") => true,
        Some("never") => false,
        _ => matches!(std::env::var("COLORTERM").as_deref(), Ok("truecolor") | Ok("24bit")),
    };
    let image_protocol = m.get_one::<String>("image-protocol").cloned();
    let color_resolution: usize = m.get_one::<String>("color-resolution").unwrap().parse().unwrap_or(64);
    let no_color_palette = m.get_flag("no-color-palette");
    let no_art = m.get_flag("no-art");
    let nerd_fonts = m.get_flag("nerd-fonts");
    let output = m.get_one::<String>("output").cloned();
    let no_title = m.get_flag("no-title");

    // Languages
    let stats = tokei::get_statistics(&workdir, &excluded, &types, include_hidden);
    let mut distribution: Vec<(usize, f64)> = Vec::new();
    let total_loc: usize = stats.by_language.iter().map(|x| x.1).sum();
    for (idx, code) in &stats.by_language {
        if *code == 0 {
            continue;
        }
        distribution.push((*idx, *code as f64));
    }
    let total: f64 = distribution.iter().map(|x| x.1).sum();
    let languages: Option<Vec<(usize, f64)>> = if total.abs() < f64::EPSILON {
        None
    } else {
        for d in distribution.iter_mut() {
            d.1 = d.1 / total * 100.0;
        }
        distribution.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap());
        Some(distribution)
    };
    let dominant = languages.as_ref().and_then(|l| l.first().map(|x| x.0));

