    let manifest = manifest::get_manifest(&workdir);
    let title = if no_title {
        None
    } else {
        Some(Title { git_username: git::committer_name(&repo), git_version: git_version() })
    };
    let metrics = git::traverse(
        &repo,
        head_oid,
        &git::TraverseOptions {
            no_bots: no_bots.as_ref(),
