        Some(u) => {
            let p = url::parse(u);
            (url::repo_name(&p.path), url::format_url(&p.display, hide_token, http_url))
        }
        None => (String::new(), String::new()),
    };

    let mut fields: Vec<InfoField> = Vec::new();
    if !is_disabled("project") {
        let (tags, branches) = git::tags_and_branches(&repo);
        fields.push(InfoField::Project { repo_name: repo_name.clone(), branches, tags });
    }
    if !is_disabled("description") {
        fields.push(InfoField::Description(manifest.as_ref().and_then(|m| m.description.clone())));
    }
    if !is_disabled("head") {
        let short = repo
            .find_object(head_oid, None)
            .ok()
