    }
    if !is_disabled("pending") {
        let p = git::pending(&repo);
        fields.push(InfoField::Pending { added: p.added, deleted: p.deleted, modified: p.modified });
    }
    if !is_disabled("version") {
        let mut v = git::version(&repo);
        if v.is_empty() {
            if let Some(m) = &manifest {
                v = m.version.clone();
            }
        }
        fields.push(InfoField::Version(v));
    }
    let time_str = |t: Option<git::GitTime>| t.map(|t| fmt::format_time(t.seconds, iso_time)).unwrap_or_default();
    if !is_disabled("created") {
        fields.push(InfoField::Created(time_str(metrics.time_of_first_commit)));
    }
    if !is_disabled("languages") {
        if let Some(l) = &languages {
            fields.push(InfoField::Languages(l.clone()));
        }
    }
    if !is_disabled("dependencies") {
        let d = match &manifest {
            Some(m) if m.number_of_dependencies > 0 => {
                format!("{} ({})", number_separator.format(m.number_of_dependencies), m.manager)
            }
            _ => String::new(),
        };
        fields.push(InfoField::Dependencies(d));
    }
    if !is_disabled("authors") {
        fields.push(InfoField::Authors(metrics.authors.clone()));
    }
    if !is_disabled("last-change") {
        fields.push(InfoField::LastChange(time_str(metrics.time_of_most_recent_commit)));
    }
    if !is_disabled("contributors") {
        fields.push(InfoField::Contributors { total: metrics.total_number_of_authors });
    }
    if !is_disabled("url") {
        fields.push(InfoField::Url(repo_url.clone()));
    }
    if !is_disabled("commits") {
        fields.push(InfoField::Commits { count: metrics.total_number_of_commits, shallow: metrics.is_shallow });
    }
    if !is_disabled("churn") {
        fields.push(InfoField::Churn { churns: metrics.file_churns.clone(), pool: metrics.churn_pool_size });
    }
    if !is_disabled("lines-of-code") && languages.is_some() {
        fields.push(InfoField::Loc(total_loc));
    }
    if !is_disabled("size") {
        let (size, count) = git::repo_size(&repo);
        fields.push(InfoField::Size { size: fmt::format_bytes(size), count });
    }
    if !is_disabled("license") {
        let lic = match manifest.as_ref().and_then(|m| m.license.clone()) {
            Some(l) => l,
            None => license::detect(&workdir),
        };
        fields.push(InfoField::License(lic));
    }

    // colors
    let color_lang = ascii_language.or(dominant);
    let mut lang_colors: Vec<DynColor> = color_lang.map(|i| LANGS[i].colors(true_color)).unwrap_or_default();
    let ascii_colors_dyn: Vec<DynColor> = if ascii_colors.is_empty() {
        lang_colors.clone()
    } else {
        let mut c: Vec<DynColor> = ascii_colors.iter().map(|n| DynColor::from_num(*n)).collect();
        if lang_colors.len() > c.len() {
            let mut missing = lang_colors.split_off(c.len());
            c.append(&mut missing);
        }
        c
    };
    let logo_primary = ascii_colors_dyn.first().copied().unwrap_or(DynColor::WHITE);
    let text_colors = TextColors::new(&text_colors_arg, logo_primary);

    let info = Info {
        title,
        fields,
        text_colors,
        no_bold,
        no_color_palette,
        number_separator,
        number_of_languages,
        number_of_authors,
        true_color,
        nerd_fonts,
        show_email,
    };

    match output.as_deref() {
        Some("json") => {
            let s = serde_json::to_string_pretty(&info.to_json_value()).unwrap();
            print!("{}", s);
            return;
        }
        Some("yaml") => {
            let s = serde_yaml::to_string(&info.to_json_value()).unwrap();
            print!("{}", s);
            return;
        }
        _ => {}
    }

    let art: Option<String> = if no_art {
        None
    } else if let Some(a) = &ascii_input {
        Some(a.clone())
    } else if let Some(i) = color_lang {
        Some(LANGS[i].art.to_string())
    } else {
        None
    };
    let info_str = info.render();
    let out = printer::print(
        &info_str,
        if no_art { None } else { image_data.as_ref() },
        image_protocol.as_deref(),
        color_resolution,
        art.as_deref(),
        &ascii_colors_dyn,
        !no_bold,
    );
    use std::io::Write;
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    lock.write_all(out.as_bytes()).expect("failed printing to stdout");
    lock.flush().expect("failed printing to stdout");
}
