//! Final layout of ascii art / image and info lines.

use crate::ascii::AsciiArt;
use crate::color::DynColor;
use std::path::Path;

pub struct Image {
    #[allow(dead_code)]
    pub width: u32,
    #[allow(dead_code)]
    pub height: u32,
    #[allow(dead_code)]
    pub rgba: Vec<u8>,
}

pub fn load_image(p: &Path) -> Result<Image, String> {
    let data = std::fs::read(p).map_err(|e| e.to_string())?;
    let _ = data;
    Err("The image format could not be determined".to_string())
}

pub fn print(
    info: &str,
    _image: Option<&Image>,
    _protocol: Option<&str>,
    _color_resolution: usize,
    art: Option<&str>,
    colors: &[DynColor],
    bold: bool,
) -> String {
    let center_pad = "   ";
    let mut buf = String::from("\x1b[?7l");
    match art {
        None => buf.push_str(info),
        Some(a) => {
            let mut logo = AsciiArt::new(a, colors, bold);
            let mut info_lines = info.lines();
            loop {
                match (logo.next(), info_lines.next()) {
                    (Some(l), Some(i)) => {
                        buf.push_str(&l);
                        buf.push_str(center_pad);
                        buf.push_str(i);
                        buf.push('\n');
                    }
                    (Some(l), None) => {
                        buf.push_str(&l);
                        buf.push('\n');
                    }
                    (None, Some(i)) => {
                        if logo.is_degenerate() {
                            panic!("assertion failed: self.end >= self.start");
                        }
                        buf.push_str(&" ".repeat(logo.width()));
                        buf.push_str(center_pad);
                        buf.push_str(i);
                        buf.push('\n');
                    }
                    (None, None) => break,
                }
            }
        }
    }
    buf.push_str("\x1b[?7h");
    buf
}
