//! License detection: text normalisation followed by a bigram Dice
//! coefficient comparison against a set of known license texts.

use crate::license_data::LICENSE_TEXTS;
use regex::Regex;
use std::collections::HashMap;
use std::path::Path;
use std::sync::OnceLock;

const MIN_THRESHOLD: f32 = 0.8;

struct Rx {
    junk: Regex,
    urls: Regex,
    hspace: Regex,
    quotes: Regex,
    dash: Regex,
    open: Regex,
    close: Regex,
    under: Regex,
    copy: Regex,
    vmisc: Regex,
    vnum: Regex,
    punct: Regex,
    title: Regex,
    copyright: Regex,
    ws: Regex,
}

fn rx() -> &'static Rx {
    static R: OnceLock<Rx> = OnceLock::new();
    R.get_or_init(|| Rx {
        junk: Regex::new(r"[^\w\s\pP]+").unwrap(),
        urls: Regex::new(r"https?://\S+").unwrap(),
        hspace: Regex::new(r"(?x)[ \t\p{Zs} \\ / \| \x{2044} ]+").unwrap(),
        quotes: Regex::new(r#"["'\p{Pi}\p{Pf}]+"#).unwrap(),
        dash: Regex::new(r"\p{Pd}+").unwrap(),
        open: Regex::new(r"\p{Ps}+").unwrap(),
        close: Regex::new(r"\p{Pe}+").unwrap(),
        under: Regex::new(r"\p{Pc}+").unwrap(),
        copy: Regex::new(r"[©Ⓒⓒ]").unwrap(),
        vmisc: Regex::new(r"[\r\n\v\f]").unwrap(),
        vnum: Regex::new(r"\n{3,}").unwrap(),
        punct: Regex::new(r"[^\w\s]+").unwrap(),
        title: Regex::new(r"^.*license( version \S+)?( copyright.*)?\n\n").unwrap(),
        copyright: Regex::new(
            r"(?mx)
            (
                (\n\n|\A\n*)
                (^\x20*copyright.*?$)+
                \n\n
            )
            |
            (
                \A.*copyright.*$
            )
            |
            (
                ^copyright\ (\(c\)\ )?(\[yyyy\]|\d{4})[,.]?.*$
            )",
        )
        .unwrap(),
        ws: Regex::new(r"\s+").unwrap(),
    })
}

fn normalize_line(line: &str) -> String {
    let r = rx();
    let mut s = r.junk.replace_all(line, "").into_owned();
    s = r.urls.replace_all(&s, "http://blackboxed").into_owned();
    s = r.hspace.replace_all(&s, " ").into_owned();
    s = r.quotes.replace_all(&s, "'").into_owned();
    s = r.dash.replace_all(&s, "-").into_owned();
    s = r.open.replace_all(&s, "(").into_owned();
    s = r.close.replace_all(&s, ")").into_owned();
    s = r.under.replace_all(&s, "_").into_owned();
    s = r.copy.replace_all(&s, "(c)").into_owned();
    s.trim().to_string()
}

fn common_prefix(a: &str, b: &str) -> Option<String> {
    let common: String = a.chars().zip(b.chars()).take_while(|(x, y)| x == y).map(|(x, _)| x).collect();
    if common.is_empty() {
        None
    } else {
        Some(common)
    }
}

fn remove_common_tokens(input: &str) -> String {
    let lines: Vec<&str> = input.split('\n').collect();
    let mut prefix_count: HashMap<String, u32> = HashMap::new();
    for w in lines.windows(2) {
        if let Some(c) = common_prefix(w[0], w[1]) {
            *prefix_count.entry(c).or_insert(0) += 1;
        }
    }
    let most_common = match prefix_count.iter().max_by(|a, b| a.1.cmp(b.1).then_with(|| b.0.cmp(a.0))) {
        Some((p, _)) => p.clone(),
        None => return input.to_string(),
    };
    let common_count: u32 = prefix_count.iter().filter(|(k, _)| k.starts_with(&most_common)).map(|(_, v)| *v).sum();
    let threshold = (0.8f32 * lines.len() as f32) as u32;
    if common_count < threshold {
        return input.to_string();
    }
    lines
        .iter()
        .map(|l| if l.starts_with(&most_common) { &l[most_common.len()..] } else { l })
        .collect::<Vec<_>>()
        .join("\n")
}

pub fn process(text: &str) -> String {
    let r = rx();
    let normalized: Vec<String> = text.split('\n').map(normalize_line).collect();
    let joined = normalized.join("\n");
    let mut s = remove_common_tokens(&joined);
    s = r.vmisc.replace_all(&s, "\n").into_owned();
    s = r.vnum.replace_all(&s, "\n\n").into_owned();
    s = r.punct.replace_all(&s, "").into_owned();
    s = s.to_lowercase();
    s = r.title.replace(&s, "").into_owned();
    s = r.copyright.replace_all(&s, "\n\n").into_owned();
    s = r.ws.replace_all(&s, " ").into_owned();
    s.trim().to_string()
}

struct NgramSet {
    map: HashMap<String, u32>,
    size: usize,
}

impl NgramSet {
    fn new(processed: &str) -> NgramSet {
        let words: Vec<&str> = processed.split(' ').collect();
        let mut map: HashMap<String, u32> = HashMap::new();
        let mut size = 0;
        for w in words.windows(2) {
            *map.entry(format!("{} {}", w[0], w[1])).or_insert(0) += 1;
            size += 1;
        }
        NgramSet { map, size }
    }

    fn dice(&self, other: &NgramSet) -> f32 {
        if self.size == 0 || other.size == 0 {
            return 0.0;
        }
        let (x, y) = if self.map.len() < other.map.len() { (self, other) } else { (other, self) };
        let mut matches = 0u32;
        for (g, c) in &x.map {
            if let Some(oc) = y.map.get(g) {
                matches += (*c).min(*oc);
            }
        }
        2.0 * matches as f32 / ((self.size + other.size) as f32)
    }
}

fn store() -> &'static Vec<(&'static str, NgramSet)> {
    static S: OnceLock<Vec<(&'static str, NgramSet)>> = OnceLock::new();
    S.get_or_init(|| LICENSE_TEXTS.iter().map(|(n, t)| (*n, NgramSet::new(&process(t)))).collect())
}

pub fn analyze(text: &str) -> Option<(&'static str, f32)> {
    let data = NgramSet::new(&process(text));
    let mut best: Option<(&'static str, f32)> = None;
    for (name, set) in store() {
        let score = data.dice(set);
        match best {
            Some((_, b)) if score <= b => {}
            _ => best = Some((name, score)),
        }
    }
    best
}

fn is_license_file(name: &str) -> bool {
    ["LICENSE", "LICENCE", "COPYING"].iter().any(|p| name.starts_with(p))
}

pub fn detect(dir: &Path) -> String {
    let mut out: Vec<String> = Vec::new();
    if let Ok(rd) = std::fs::read_dir(dir) {
        for e in rd.flatten() {
            let p = e.path();
            let name = match p.file_name() {
                Some(n) => n.to_string_lossy().into_owned(),
                None => continue,
            };
            if !p.is_file() || !is_license_file(&name) {
                continue;
            }
            let contents = std::fs::read_to_string(&p).unwrap_or_default();
            if let Some((n, score)) = analyze(&contents) {
                if score >= MIN_THRESHOLD {
                    out.push(n.to_string());
                }
            }
        }
    }
    out.sort();
    out.dedup();
    out.join(", ")
}
