//! Image loading (validation) and terminal image protocols.

use std::path::Path;

pub struct LoadedImage {
    #[allow(dead_code)]
    pub data: Vec<u8>,
}

/// Returns the error chain lines on failure.
pub fn load(path: &Path) -> Result<LoadedImage, Vec<String>> {
    let data = match std::fs::read(path) {
        Ok(d) => d,
        Err(e) => {
            if path.is_dir() {
                return Err(vec!["The image format could not be determined".to_string()]);
            }
            return Err(vec![io_error_string(&e)]);
        }
    };
    let ext = path
        .file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .and_then(|n| match n.rfind('.') {
            Some(0) | None => None,
            Some(i) => Some(n[i + 1..].to_string()),
        });
    let ext = match ext {
        Some(e) => e,
        None => return Err(vec!["The image format could not be determined".to_string()]),
    };
    let format = match ext.to_lowercase().as_str() {
        "png" => "Png",
        "jpg" | "jpeg" | "jpe" | "jif" | "jfif" => "Jpeg",
        "webp" => "WebP",
        "gif" => "Gif",
        "bmp" => "Bmp",
        "ico" => "Ico",
        "tif" | "tiff" => "Tiff",
        "tga" => "Tga",
        "dds" => "Dds",
        "hdr" => "Hdr",
        "exr" => "OpenExr",
        "pbm" | "pam" | "ppm" | "pgm" | "pnm" => "Pnm",
        "ff" => "Farbfeld",
        "avif" => "Avif",
        "qoi" => "Qoi",
        _ => {
            return Err(vec![format!(
                "The file extension `.\"{}\"` was not recognized as an image format",
                ext
            )])
        }
    };
    match format {
        "Png" => {
            if data.len() < 8 || &data[..8] != b"\x89PNG\r\n\x1a\n" {
                return Err(vec![
                    "Format error decoding Png: Invalid PNG signature.".to_string(),
                    "Invalid PNG signature.".to_string(),
                ]);
            }
            if data.len() < 33 {
                return Err(vec!["unexpected end of file".to_string()]);
            }
        }
        "Jpeg" => {
            if data.len() < 2 || data[0] != 0xFF || data[1] != 0xD8 {
                let b0 = data.first().copied().unwrap_or(0);
                let b1 = data.get(1).copied().unwrap_or(0);
                return Err(vec![
                    format!("Format error decoding Jpeg: Error parsing image. Illegal start bytes:{:X}{:X}", b0, b1),
                    format!("Error parsing image. Illegal start bytes:{:X}{:X}", b0, b1),
                ]);
            }
        }
        "WebP" => {
            if data.len() < 12 || &data[..4] != b"RIFF" || &data[8..12] != b"WEBP" {
                let h: Vec<String> = data.iter().take(4).map(|b| b.to_string()).collect();
                return Err(vec![
                    format!("Format error decoding WebP: Invalid Chunk header: [{}]", h.join(", ")),
                    format!("Invalid Chunk header: [{}]", h.join(", ")),
                ]);
            }
        }
        other => return Err(vec![format!("The image format {} is not supported", other)]),
    }
    Ok(LoadedImage { data })
}

pub fn io_error_string(e: &std::io::Error) -> String {
    let s = e.to_string();
    s
}

pub fn is_tty(fd: i32) -> bool {
    unsafe { libc::isatty(fd) == 1 }
}

/// Formats an error with its chain the way `anyhow` does.
pub fn format_error(msg: &str, causes: &[String]) -> String {
    let mut s = format!("Error: {}", msg);
    if !causes.is_empty() {
        s.push_str("\n\nCaused by:");
        if causes.len() == 1 {
            s.push_str(&format!("\n    {}", causes[0]));
        } else {
            for (i, c) in causes.iter().enumerate() {
                s.push_str(&format!("\n    {}: {}", i, c));
            }
        }
    }
    s
}
