/// Mirrors a binary search over captures sorted by start position, returning
/// the captures from the first one starting at or after `start`.
fn filter_range(caps: &[(usize, usize)], start: usize, end: usize) -> Option<Vec<(usize, usize)>> {
    let pos = match caps.binary_search_by_key(&start, |c| c.0) {
        Ok(p) => p,
        Err(p) => p,
    };
    if pos >= caps.len() || caps[pos].0 > end {
        return None;
    }
    Some(caps[pos..].iter().take_while(|c| c.1 <= end).copied().collect())
}

fn end_captures(lines: &[u8], line_start: usize, closing: &[u8]) -> Vec<(usize, usize)> {
    let mut out = Vec::new();
    let mut pos = line_start;
    while let Some(p) = find_at(lines, closing, pos) {
        out.push((p, p + closing.len()));
        pos = p + closing.len();
    }
    out
}

pub fn parse_html_context(lines: &[u8], line_start: usize, start: usize, end: usize) -> Option<super::counter::Analysis> {
