/// Validates a field the way the strongly typed package.json model would.
fn npm_field_ok(key: &str, v: &serde_json::Value) -> bool {
    use serde_json::Value as V;
    let string_map = |v: &V| matches!(v, V::Object(m) if m.values().all(|x| x.is_string()));
    let string_vec = |v: &V| matches!(v, V::Array(a) if a.iter().all(|x| x.is_string()));
    let opt_str_fields = |m: &serde_json::Map<String, V>, keys: &[&str]| {
