/// Decoded RGBA8 image.
pub struct Rgba {
    pub width: u32,
    pub height: u32,
    pub data: Vec<u8>,
}

fn paeth(a: u8, b: u8, c: u8) -> u8 {
    let p = a as i16 + b as i16 - c as i16;
    let pa = (p - a as i16).abs();
    let pb = (p - b as i16).abs();
    let pc = (p - c as i16).abs();
    if pa <= pb && pa <= pc {
        a
    } else if pb <= pc {
        b
    } else {
        c
    }
}

fn unfilter(data: &[u8], width: usize, height: usize, bpp: usize, bits_pp: usize) -> Option<Vec<Vec<u8>>> {
    let stride = (width * bits_pp + 7) / 8;
    let mut rows: Vec<Vec<u8>> = Vec::with_capacity(height);
    let mut pos = 0;
    let mut prev = vec![0u8; stride];
    for _ in 0..height {
        if pos + 1 + stride > data.len() {
            return None;
        }
        let ft = data[pos];
        let mut cur = data[pos + 1..pos + 1 + stride].to_vec();
        pos += 1 + stride;
        for i in 0..stride {
            let a = if i >= bpp { cur[i - bpp] } else { 0 };
            let b = prev[i];
            let c = if i >= bpp { prev[i - bpp] } else { 0 };
            cur[i] = match ft {
                0 => cur[i],
                1 => cur[i].wrapping_add(a),
                2 => cur[i].wrapping_add(b),
                3 => cur[i].wrapping_add(((a as u16 + b as u16) / 2) as u8),
                4 => cur[i].wrapping_add(paeth(a, b, c)),
                _ => return None,
            };
        }
        prev = cur.clone();
        rows.push(cur);
    }
    Some(rows)
}

fn sample(row: &[u8], x: usize, depth: usize) -> u16 {
    match depth {
        8 => row[x] as u16,
        16 => ((row[2 * x] as u16) << 8) | row[2 * x + 1] as u16,
        d => {
            let per = 8 / d;
            let byte = row[x / per];
            let shift = 8 - d * (x % per + 1);
            ((byte >> shift) & ((1u8 << d) - 1)) as u16
        }
    }
}

/// Decodes a PNG file into RGBA8 pixels.
pub fn decode_png(data: &[u8]) -> Option<Rgba> {
    if data.len() < 8 || &data[..8] != b"\x89PNG\r\n\x1a\n" {
        return None;
    }
    let mut pos = 8;
    let (mut w, mut h, mut depth, mut ctype, mut interlace) = (0usize, 0usize, 0usize, 0u8, 0u8);
    let mut plte: Vec<u8> = Vec::new();
    let mut trns: Vec<u8> = Vec::new();
    let mut idat: Vec<u8> = Vec::new();
    while pos + 8 <= data.len() {
        let len = u32::from_be_bytes([data[pos], data[pos + 1], data[pos + 2], data[pos + 3]]) as usize;
        let ty = &data[pos + 4..pos + 8];
        let body = data.get(pos + 8..pos + 8 + len)?;
        match ty {
            b"IHDR" => {
                w = u32::from_be_bytes([body[0], body[1], body[2], body[3]]) as usize;
                h = u32::from_be_bytes([body[4], body[5], body[6], body[7]]) as usize;
                depth = body[8] as usize;
                ctype = body[9];
                interlace = body[12];
            }
            b"PLTE" => plte = body.to_vec(),
            b"tRNS" => trns = body.to_vec(),
            b"IDAT" => idat.extend_from_slice(body),
            b"IEND" => break,
            _ => {}
        }
        pos += 12 + len;
    }
    use std::io::Read;
    let mut raw = Vec::new();
    flate2::read::ZlibDecoder::new(&idat[..]).read_to_end(&mut raw).ok()?;
    let channels = match ctype {
        0 => 1,
        2 => 3,
        3 => 1,
        4 => 2,
        6 => 4,
        _ => return None,
    };
    let bits_pp = channels * depth;
    let bpp = std::cmp::max(1, bits_pp / 8);
    let mut out = vec![0u8; w * h * 4];
    let maxv = ((1u32 << depth) - 1) as u32;
    let to8 = |v: u16| -> u8 {
        if depth == 16 {
            (v >> 8) as u8
        } else if depth == 8 {
            v as u8
        } else {
            ((v as u32 * 255) / maxv) as u8
        }
    };
    let mut put = |x: usize, y: usize, row: &[u8], rx: usize| {
        let o = (y * w + x) * 4;
        let px: [u8; 4] = match ctype {
            0 => {
                let v = sample(row, rx, depth);
                let g = to8(v);
                let a = if trns.len() >= 2 && v == u16::from_be_bytes([trns[0], trns[1]]) { 0 } else { 255 };
                [g, g, g, a]
            }
            2 => {
                let r = sample(row, rx * 3, depth);
                let g = sample(row, rx * 3 + 1, depth);
                let b = sample(row, rx * 3 + 2, depth);
                let a = if trns.len() >= 6
                    && r == u16::from_be_bytes([trns[0], trns[1]])
                    && g == u16::from_be_bytes([trns[2], trns[3]])
                    && b == u16::from_be_bytes([trns[4], trns[5]])
                {
                    0
                } else {
                    255
                };
                [to8(r), to8(g), to8(b), a]
            }
            3 => {
                let i = sample(row, rx, depth) as usize;
                let r = *plte.get(i * 3).unwrap_or(&0);
                let g = *plte.get(i * 3 + 1).unwrap_or(&0);
                let b = *plte.get(i * 3 + 2).unwrap_or(&0);
                let a = if trns.is_empty() { 255 } else { *trns.get(i).unwrap_or(&255) };
                [r, g, b, a]
            }
            4 => {
                let g = to8(sample(row, rx * 2, depth));
                let a = to8(sample(row, rx * 2 + 1, depth));
                [g, g, g, a]
            }
            _ => {
                let r = to8(sample(row, rx * 4, depth));
                let g = to8(sample(row, rx * 4 + 1, depth));
                let b = to8(sample(row, rx * 4 + 2, depth));
                let a = to8(sample(row, rx * 4 + 3, depth));
                [r, g, b, a]
            }
        };
        out[o..o + 4].copy_from_slice(&px);
    };
    if interlace == 0 {
        let rows = unfilter(&raw, w, h, bpp, bits_pp)?;
        for (y, row) in rows.iter().enumerate() {
            for x in 0..w {
                put(x, y, row, x);
            }
        }
    } else {
        let passes = [(0, 0, 8, 8), (4, 0, 8, 8), (0, 4, 4, 8), (2, 0, 4, 4), (0, 2, 2, 4), (1, 0, 2, 2), (0, 1, 1, 2)];
        let mut offset = 0;
        for (x0, y0, dx, dy) in passes {
            if x0 >= w || y0 >= h {
                continue;
            }
            let pw = (w - x0 + dx - 1) / dx;
            let ph = (h - y0 + dy - 1) / dy;
            let stride = (pw * bits_pp + 7) / 8;
            let size = ph * (stride + 1);
            let rows = unfilter(raw.get(offset..offset + size)?, pw, ph, bpp, bits_pp)?;
            offset += size;
            for (py, row) in rows.iter().enumerate() {
                for px in 0..pw {
                    put(x0 + px * dx, y0 + py * dy, row, px);
                }
            }
        }
    }
    Some(Rgba { width: w as u32, height: h as u32, data: out })
}

fn sinc(t: f32) -> f32 {
    let a = t * std::f32::consts::PI;
    if t == 0.0 {
        1.0
    } else {
        a.sin() / a
    }
}

fn lanczos3(x: f32) -> f32 {
    if x.abs() < 3.0 {
        sinc(x) * sinc(x / 3.0)
    } else {
        0.0
    }
}

fn weights(in_size: u32, out_size: u32, out_i: u32) -> (u32, Vec<f32>) {
    let ratio = in_size as f32 / out_size as f32;
    let sratio = if ratio < 1.0 { 1.0 } else { ratio };
    let src_support = 3.0 * sratio;
    let input = (out_i as f32 + 0.5) * ratio;
    let left = (input - src_support).floor() as i64;
    let left = left.clamp(0, in_size as i64 - 1) as u32;
    let right = (input + src_support).ceil() as i64;
    let right = right.clamp(left as i64 + 1, in_size as i64) as u32;
    let input = input - 0.5;
    let mut ws = Vec::new();
    let mut sum = 0.0;
    for i in left..right {
        let w = lanczos3((i as f32 - input) / sratio);
        ws.push(w);
        sum += w;
    }
    ws.iter_mut().for_each(|w| *w /= sum);
    (left, ws)
}

/// Lanczos3 resampling (vertical pass then horizontal pass).
pub fn resize_exact(img: &Rgba, nw: u32, nh: u32) -> Rgba {
    if nw == img.width && nh == img.height {
        return Rgba { width: nw, height: nh, data: img.data.clone() };
    }
    let (w, h) = (img.width, img.height);
    let mut tmp = vec![0f32; (w * nh * 4) as usize];
    for oy in 0..nh {
        let (left, ws) = weights(h, nh, oy);
        for x in 0..w {
            let mut t = [0f32; 4];
            for (i, wt) in ws.iter().enumerate() {
                let o = (((left + i as u32) * w + x) * 4) as usize;
                for c in 0..4 {
                    t[c] += img.data[o + c] as f32 * wt;
                }
            }
            let o = ((oy * w + x) * 4) as usize;
            tmp[o..o + 4].copy_from_slice(&t);
        }
    }
    let mut out = vec![0u8; (nw * nh * 4) as usize];
    for ox in 0..nw {
        let (left, ws) = weights(w, nw, ox);
        for y in 0..nh {
            let mut t = [0f32; 4];
            for (i, wt) in ws.iter().enumerate() {
                let o = ((y * w + left + i as u32) * 4) as usize;
                for c in 0..4 {
                    t[c] += tmp[o + c] * wt;
                }
            }
            let o = ((y * nw + ox) * 4) as usize;
            for c in 0..4 {
                out[o + c] = t[c].clamp(0.0, 255.0).round() as u8;
            }
        }
    }
    Rgba { width: nw, height: nh, data: out }
}

/// Aspect-ratio preserving resize.
pub fn resize(img: &Rgba, nwidth: u32, nheight: u32) -> Rgba {
    if (nwidth, nheight) == (img.width, img.height) {
        return Rgba { width: img.width, height: img.height, data: img.data.clone() };
    }
    let (width, height) = (img.width, img.height);
    let wratio = nwidth as f64 / width as f64;
    let hratio = nheight as f64 / height as f64;
    let ratio = f64::min(wratio, hratio);
    let nw = std::cmp::max((width as f64 * ratio).round() as u64, 1);
    let nh = std::cmp::max((height as f64 * ratio).round() as u64, 1);
    let (w2, h2) = if nw > u32::MAX as u64 {
        let ratio = u32::MAX as f64 / width as f64;
        (u32::MAX, std::cmp::max((height as f64 * ratio).round() as u32, 1))
    } else if nh > u32::MAX as u64 {
        let ratio = u32::MAX as f64 / height as f64;
        (std::cmp::max((width as f64 * ratio).round() as u32, 1), u32::MAX)
    } else {
        (nw as u32, nh as u32)
    };
    resize_exact(img, w2, h2)
}

pub fn tty_size() -> Option<libc::winsize> {
    unsafe {
        let mut ws: libc::winsize = std::mem::zeroed();
        if libc::ioctl(libc::STDOUT_FILENO, libc::TIOCGWINSZ, &mut ws) == 0 {
            Some(ws)
        } else {
            None
        }
    }
}

/// Kitty graphics protocol rendering next to the info lines.
pub fn kitty(lines: &[String], img: &Rgba, ws: &libc::winsize) -> String {
    let height_ratio = ws.ws_row as f64 / ws.ws_ypixel as f64;
    let target = (lines.len() as f64 / height_ratio) as u32;
    let image = resize(img, u32::MAX, target);
    let image_rows = height_ratio * image.height as f64;
    let encoded = base64(&image.data);
    let mut out = String::new();
    for chunk in encoded.as_bytes().chunks(4096) {
        out.push_str(&format!("\x1b_Gf=32,s={},v={},m=1,a=T;", image.width, image.height));
        out.push_str(std::str::from_utf8(chunk).unwrap_or(""));
        out.push_str("\x1b\\");
    }
    out.push_str("\x1b_Gm=0;\x1b\\");
    out.push_str(&format!("\x1b[{}A", (image_rows as u32).wrapping_sub(1)));
    let mut i = 0usize;
    for line in lines {
        out.push_str(&format!("\x1b[s{}\x1b[u\x1b[1B", line));
        i += 1;
    }
    out.push_str(&format!("\n\x1b[{}B", std::cmp::max(lines.len(), image_rows as usize).wrapping_sub(i)));
    out
}
